gqe(){return"TruthLens\ub294 \uc0ac\uc6a9\uc790\uc758 \uc2e0\uc6d0\uacfc \uc5f0\uacb0\ub41c \ub370\uc774\ud130\ub97c \uc804\ud600 \uc218\uc9d1\ud558\uc9c0 \uc54a\uc73c\uba70 \ucd94\uc801 \ubaa9\uc801\uc73c\ub85c \uc5b4\ub5a4 \ub370\uc774\ud130\ub3c4 \uc0ac\uc6a9\ud558\uc9c0 \uc54a\uc73c\ubbc0\ub85c \uc571 \ucd94\uc801 \ud22c\uba85\uc131\uff08ATT\uff09 \uad8c\ud55c\uc774 \ud544\uc694\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
gqf(){return"\uc774 \uc571\uc740 \uc2dc\uc2a4\ud15c\uc5d0\uc11c \uc81c\uacf5\ud558\ub294 \ud30c\uc77c \uc120\ud0dd \ub3c4\uad6c\ub97c \uc0ac\uc6a9\ud558\uc5ec \uc0ac\uc6a9\uc790\uac00 \ub2a5\ub3d9\uc801\uc73c\ub85c \uc120\ud0dd\ud55c \ubb38\uc11c\ub098 \uc774\ubbf8\uc9c0\uc5d0 \uc811\uadfc\ud569\ub2c8\ub2e4. \uc120\ud0dd\ud558\uc9c0 \uc54a\uc740 \ud30c\uc77c\uc5d0\ub294 \uc811\uadfc\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4\uff08iOS \uc571 \uc0cc\ub4dc\ubc15\uc2a4 \uc81c\ud55c\uff09."},
gq6(){return"TruthLens\ub294 \uac1c\uc778 \ub370\uc774\ud130\ub97c \uc218\uc9d1\ud558\uc9c0 \uc54a\uc73c\uba70 \uc5b4\ub5a4 \uc81c3\uc790\uc640\ub3c4 \uc0ac\uc6a9\uc790 \ub370\uc774\ud130\ub97c \uacf5\uc720\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
gq7(){return"\uc774 \uc571\uc740 \uc0ac\uc6a9\uc790\uac00 \ub2a5\ub3d9\uc801\uc73c\ub85c \ubb38\uc11c\ub098 \uc774\ubbf8\uc9c0 \uac00\uc838\uc624\uae30\ub97c \uc120\ud0dd\ud560 \ub54c\ub9cc \ud574\ub2f9 \uc800\uc7a5\uc18c \uad8c\ud55c\uc5d0 \uc811\uadfc\ud558\uba70, \ubc31\uadf8\ub77c\uc6b4\ub4dc\uc5d0\uc11c \ub2e4\ub978 \ud30c\uc77c\uc744 \uc2a4\uce94\ud558\uac70\ub098 \uc811\uadfc\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
gqh(){return"TruthLens\ub294 macOS \uc571 \uc0cc\ub4dc\ubc15\uc2a4 \ud558\uc5d0\uc11c \uc2e4\ud589\ub418\uba70, \uc2dc\uc2a4\ud15c \ud30c\uc77c \ub300\ud654 \uc0c1\uc790\ub97c \ud1b5\ud574 \uc0ac\uc6a9\uc790\uac00 \ub2a5\ub3d9\uc801\uc73c\ub85c \uc120\ud0dd\ud55c \ud30c\uc77c\uff08files.user-selected.read-write\uff09\uc5d0\ub9cc \uc811\uadfc\ud560 \uc218 \uc788\uace0, \ub2e4\ub978 \ud30c\uc77c\uc774\ub098 \ud3f4\ub354\ub97c \uc790\uc720\ub86d\uac8c \ud0d0\uc0c9\ud558\uac70\ub098 \uc811\uadfc\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4."},
gqi(){return'\ub124\ud2b8\uc6cc\ud06c \uc811\uadfc \uad8c\ud55c\uff08network.client\uff09\uc740 \uc544\ub798 "\ud544\uc694\ud55c \uc5f0\uacb0 \ub3d9\uc791"\uc5d0 \ub098\uc5f4\ub41c \uae30\ub2a5\uc5d0\ub9cc \uc0ac\uc6a9\ub429\ub2c8\ub2e4.'},
gqA(){return"TruthLens\ub294 \ub3c5\ub9bd \uc2e4\ud589\ud615 \ub370\uc2a4\ud06c\ud1b1 \uc560\ud50c\ub9ac\ucf00\uc774\uc158\uc73c\ub85c, \ub370\uc774\ud130\ub294 \ub85c\uceec \uc0ac\uc6a9\uc790 \ud3f4\ub354\uff08AppData\uff0fDocuments \ub4f1\uff09\uc5d0 \uc800\uc7a5\ub418\uba70 \ud074\ub77c\uc6b0\ub4dc\uc5d0 \ub3d9\uae30\ud654\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
gqB(){return"\uc774 \uc571\uc740 \uc0ac\uc6a9\uc790\uac00 \ub2a5\ub3d9\uc801\uc73c\ub85c \ubb38\uc11c\ub098 \uc774\ubbf8\uc9c0 \uac00\uc838\uc624\uae30\ub97c \uc120\ud0dd\ud560 \ub54c\ub9cc \ud574\ub2f9 \ud30c\uc77c\uc5d0 \uc811\uadfc\ud558\uba70, \ubc31\uadf8\ub77c\uc6b4\ub4dc\uc5d0\uc11c \ub2e4\ub978 \ud30c\uc77c\uc744 \uc2a4\uce94\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
gq9(){return"TruthLens\uc5d0\ub294 \uc0ac\uc6a9\uc790 \uacc4\uc815\uc774 \uc5c6\uc73c\uba70 \ub85c\uadf8\uc778\uc774 \ud544\uc694\ud558\uc9c0 \uc54a\uace0, \uc5b4\ub5a4 \ud615\ud0dc\uc758 \uad11\uace0\ub098 \uc81c3\uc790 \ucd94\uc801 SDK\ub3c4 \ud3ec\ud568\ub418\uc5b4 \uc788\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
gqa(){return"\uc0ac\uc6a9\uc790\uac00 \uc785\ub825, \ubd99\uc5ec\ub123\uae30 \ub610\ub294 \uac00\uc838\uc628 \ubb38\uc11c \ub0b4\uc6a9\uc740 \ubaa8\ub450 \uc0ac\uc6a9\uc790\uc758 \uae30\uae30\uc5d0\uc11c \ub85c\uceec AI \ubaa8\ub378\uc5d0 \uc758\ud574 \ubd84\uc11d\ub418\uba70, TruthLens\ub098 \uc5b4\ub5a4 \uc81c3\uc790 \uc11c\ubc84\uc5d0\ub3c4 \uc5c5\ub85c\ub4dc\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
gqb(){return"\ubd84\uc11d \uacb0\uacfc\uc640 \uae30\ub85d\uc740 \uc0ac\uc6a9\uc790 \uae30\uae30\uc758 \ub85c\uceec \ub370\uc774\ud130\ubca0\uc774\uc2a4\uc5d0\ub9cc \uc800\uc7a5\ub429\ub2c8\ub2e4. \uc571\uc744 \uc0ad\uc81c\ud558\uac70\ub098 \uae30\ub85d\uc744 \uc9c0\uc6b0\uba74 \ud568\uaed8 \uc81c\uac70\ub418\uba70, TruthLens\ub294 \uc5b4\ub5a4 \uc0ac\ubcf8\ub3c4 \ubcf4\uad00\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
gqn(){return"\uc774 \uc571\uc758 \ud575\uc2ec AI \uac10\uc9c0\ub294 \uc644\uc804\ud788 \uae30\uae30 \ub0b4\uc5d0\uc11c \uc2e4\ud589\ub418\uc9c0\ub9cc, \ub2e4\uc74c \uc138 \uac00\uc9c0 \uae30\ub2a5\uc740 \ub124\ud2b8\uc6cc\ud06c \uc5f0\uacb0\uc774 \ud544\uc694\ud569\ub2c8\ub2e4:"},
gqj(){return"1. \ubaa8\ub378 \uce74\ud0c8\ub85c\uadf8 \ubc0f \ub2e4\uc6b4\ub85c\ub4dc: GitHub Releases\uff0fHugging Face\uc5d0 \uc5f0\uacb0\ud558\uc5ec \uc120\ud0dd\ud55c \uac10\uc9c0 \ubaa8\ub378 \ud30c\uc77c\uc744 \ub2e4\uc6b4\ub85c\ub4dc\ud569\ub2c8\ub2e4. \ubaa8\ub378 \ub2e4\uc6b4\ub85c\ub4dc\ub9cc \uc218\ud589\ud558\uba70 \uc0ac\uc6a9\uc790 \ub370\uc774\ud130\ub97c \uc5c5\ub85c\ub4dc\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4."},
gqk(){return"2. \ubaa8\ub378 \uc5c5\ub370\uc774\ud2b8 \ud655\uc778: \uc2e4\ud589 \uc2dc \ubc84\uc804 \ubc88\ud638\ub9cc \ube44\uad50\ud558\uae30 \uc704\ud574 \uc5f0\uacb0\ud558\uba70, \uc0c8 \ubc84\uc804\uc774 \uc788\ub294\uc9c0 \uc54c\ub9ac\ub294 \ub370 \uc0ac\uc6a9\ub429\ub2c8\ub2e4."},
gql(){return'3. \ud558\uc774\ud37c\ub9c1\ud06c \ubc0f \uc778\uc6a9 \ubb38\ud5cc \uc2e4\uc7ac\uc131 \uac80\uc99d: \uae30\ubcf8\uc801\uc73c\ub85c \ucf1c\uc838 \uc788\uc73c\uba70 "\uc124\uc815"\uc5d0\uc11c \ub04c \uc218 \uc788\uc2b5\ub2c8\ub2e4. \ucf1c\uc838 \uc788\uc73c\uba74 \ubb38\uc11c\uc5d0\uc11c \uac10\uc9c0\ub41c URL\uc774\ub098 \ucc38\uace0 \ubb38\ud5cc \ud14d\uc2a4\ud2b8\ub97c \ud574\ub2f9 URL \uc790\uccb4 \ub610\ub294 Crossref \uacf5\uac1c API\ub85c \uc9c1\uc811 \uc804\uc1a1\ud569\ub2c8\ub2e4. URL\uff0fDOI\uff0f\uc11c\uc9c0 \uc815\ubcf4 \ud14d\uc2a4\ud2b8\ub9cc \uc804\uc1a1\ud558\uba70 \ubb38\uc11c\uc758 \ub2e4\ub978 \ub0b4\uc6a9\uc740 \ud3ec\ud568\ud558\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4.'},
